  "inlineSchema": "// Configuração do Prisma para o projeto DiixWhatsapp\n// Banco de dados: PostgreSQL\n// Modelo multi-tenant com isolamento lógico\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// Enum para Roles (Papéis do Usuário)\nenum Role {\n  SUPER_ADMIN // Dono da plataforma - acesso total\n  TENANT_ADMIN // Dono da loja - acesso ao seu tenant\n  ATTENDANT // Atendente - acesso limitado\n  VIEWER // Apenas visualização\n}\n\n// Enum para Status do Tenant\nenum TenantStatus {\n  ACTIVE\n  SUSPENDED\n  INACTIVE\n  TRIAL\n}\n\n// Enum para Planos\nenum PlanType {\n  FREE\n  BASIC\n  PRO\n  ENTERPRISE\n}\n\n// Tenant (Loja/Empresa)\nmodel Tenant {\n  id          String       @id @default(uuid())\n  name        String\n  slug        String       @unique\n  email       String\n  phone       String?\n  plan        PlanType     @default(FREE)\n  status      TenantStatus @default(TRIAL)\n  maxAccounts Int          @default(3)\n  maxMessages Int          @default(500)\n  trialEndsAt DateTime?\n  createdAt   DateTime     @default(now())\n  updatedAt   DateTime     @updatedAt\n\n  // Relacionamentos\n  accounts      WhatsAppAccount[]\n  users         User[]\n  conversations Conversation[]\n  orders        Order[]\n  configs       TenantConfig[]\n  products      Product[]\n  auditLogs     AuditLog[]\n\n  @@index([slug])\n  @@index([status])\n  @@index([plan])\n}\n\n// Usuários do sistema (administradores de cada tenant + Super Admin)\nmodel User {\n  id        String    @id @default(uuid())\n  tenantId  String? // Null para SUPER_ADMIN\n  email     String\n  password  String\n  name      String\n  role      Role      @default(VIEWER)\n  status    String    @default(\"active\") // active, inactive, blocked\n  lastLogin DateTime?\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n\n  tenant Tenant? @relation(fields: [tenantId], references: [id])\n\n  @@unique([email])\n  @@index([tenantId])\n  @@index([role])\n}\n\n// Contas WhatsApp vinculadas a cada tenant\nmodel WhatsAppAccount {\n  id             String    @id @default(uuid())\n  tenantId       String\n  name           String\n  instanceId     String    @unique // ID da instância na Evolution API\n  phoneNumber    String\n  status         String    @default(\"pending\") // pending, connected, disconnected\n  webhookUrl     String?\n  apiKey         String?\n  qrcode         String?\n  lastConnection DateTime?\n  createdAt      DateTime  @default(now())\n  updatedAt      DateTime  @updatedAt\n\n  tenant   Tenant    @relation(fields: [tenantId], references: [id])\n  messages Message[]\n\n  @@unique([tenantId, instanceId])\n  @@index([tenantId])\n  @@index([status])\n}\n\n// Mensagens enviadas/recebidas\nmodel Message {\n  id             String   @id @default(uuid())\n  tenantId       String\n  accountId      String\n  direction      String // inbound, outbound\n  fromNumber     String\n  toNumber       String\n  content        String\n  messageType    String   @default(\"text\") // text, image, video, audio, document, location, contact\n  status         String   @default(\"pending\") // pending, sent, delivered, read, failed\n  metadata       Json? // Dados adicionais (URLs de mídia, etc)\n  conversationId String?\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  account      WhatsAppAccount @relation(fields: [accountId], references: [id])\n  conversation Conversation?   @relation(fields: [conversationId], references: [id])\n\n  @@index([tenantId])\n  @@index([accountId])\n  @@index([conversationId])\n  @@index([createdAt])\n}\n\n// Conversas (sessões de atendimento)\nmodel Conversation {\n  id            String   @id @default(uuid())\n  tenantId      String\n  accountId     String\n  contactNumber String\n  contactName   String?\n  status        String   @default(\"open\") // open, closed, pending\n  stage         String   @default(\"initial\") // initial, qualification, proposal, negotiation, closed\n  assignedTo    String? // ID do usuário responsável\n  metadata      Json? // Dados da conversa (tags, informações do cliente, etc)\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  tenant   Tenant    @relation(fields: [tenantId], references: [id])\n  messages Message[]\n\n  @@index([tenantId])\n  @@index([accountId])\n  @@index([status])\n  @@index([stage])\n}\n\n// Pedidos/Vendas gerados pelo bot\nmodel Order {\n  id             String   @id @default(uuid())\n  tenantId       String\n  conversationId String\n  customerId     String\n  customerName   String\n  customerPhone  String\n  totalAmount    Decimal  @db.Decimal(10, 2)\n  status         String   @default(\"pending\") // pending, confirmed, processing, shipped, delivered, cancelled\n  items          Json // Lista de itens do pedido\n  paymentMethod  String?\n  paymentStatus  String   @default(\"pending\") // pending, paid, refunded\n  notes          String?\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  tenant Tenant @relation(fields: [tenantId], references: [id])\n\n  @@index([tenantId])\n  @@index([status])\n  @@index([createdAt])\n}\n\n// Produtos/Catálogo por Tenant\nmodel Product {\n  id          String   @id @default(uuid())\n  tenantId    String\n  name        String\n  description String?\n  sku         String?\n  price       Decimal  @db.Decimal(10, 2)\n  costPrice   Decimal? @db.Decimal(10, 2)\n  stock       Int      @default(0)\n  category    String?\n  images      Json? // Array de URLs de imagens\n  active      Boolean  @default(true)\n  featured    Boolean  @default(false)\n  metadata    Json? // Dados adicionais (variações, atributos, etc)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  tenant Tenant @relation(fields: [tenantId], references: [id])\n\n  @@unique([tenantId, sku])\n  @@index([tenantId])\n  @@index([category])\n  @@index([active])\n  @@index([featured])\n}\n\n// Configurações do tenant\nmodel TenantConfig {\n  id          String   @id @default(uuid())\n  tenantId    String\n  key         String\n  value       Json\n  description String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  tenant Tenant @relation(fields: [tenantId], references: [id])\n\n  @@unique([tenantId, key])\n  @@index([tenantId])\n}\n\n// Logs de auditoria\nmodel AuditLog {\n  id         String   @id @default(uuid())\n  tenantId   String?\n  userId     String?\n  action     String\n  resource   String\n  resourceId String?\n  details    Json?\n  ipAddress  String?\n  userAgent  String?\n  createdAt  DateTime @default(now())\n\n  tenant Tenant? @relation(fields: [tenantId], references: [id])\n\n  @@index([tenantId])\n  @@index([action])\n  @@index([createdAt])\n  @@index([userId])\n}\n",
